import data from './economy.json' with { type: 'json' };

/** Every economic number of the game, from economy.json (generated by tools/economy/model.mts; see
 *  docs/draft-economy-v2.md). Nothing else in the code holds a price, health, bonus or multiplier. Checked once
 *  at load: prices rise, numbers are round (two significant figures), gates never go back. */
export type CurrencyId = 'gold' | 'tech' | 'star';
export type WorldNumber = 1 | 2 | 3;
type Block = Readonly<{ itemId: string; hp: number; price: number }>;
export type LayerEconomy = Readonly<{
  world: WorldNumber; layer: number; from: number; deepAt: number | null; gate: number; oreChance: number; capsuleCoins: number;
  rock: Block; deep: Block; ores: readonly Readonly<Block & { weight: number }>[];
}>;
export type ToolEconomy = Readonly<{ level: number; currency: CurrencyId; price: number; power: number; speed: number;
  enhance: readonly Readonly<{ price: number; power: number }>[] }>;
export type BagEconomy = Readonly<{ tier: number; currency: CurrencyId; price: number; capacity: number }>;
export type TicketEconomy = Readonly<{ currency: CurrencyId; price: number; toolLevel: number;
  materials: readonly Readonly<{ itemId: string; count: number; world: WorldNumber; layer: number }>[] }>;
export type EggEconomy = Readonly<{ id: string | null; world: WorldNumber; layer: number; premium: boolean; currency: CurrencyId; price: number;
  /** `bonusPct`: income in the egg's currency; `miningPct`: mining speed in every world (percent). */
  pets: readonly Readonly<{ id: string | null; weight: number; bonusPct: number; miningPct: number }>[] }>;
export type Economy = Readonly<{
  currencies: readonly Readonly<{ id: CurrencyId; name: string; world: WorldNumber }>[];
  start: Readonly<{ toolLevel: number; bagTier: number; petSlots: number }>;
  worlds: readonly Readonly<{ id: WorldNumber; currency: CurrencyId; ticket: TicketEconomy | null }>[];
  layers: readonly LayerEconomy[];
  tools: readonly ToolEconomy[];
  bags: readonly BagEconomy[];
  petSlots: readonly Readonly<{ slot: number; currency: CurrencyId; price: number; world: WorldNumber; layer: number }>[];
  eggs: readonly EggEconomy[];
  golden: Readonly<{ need: number; bonusMultiplier: number }>;
  rebirth: Readonly<{ world: WorldNumber; layer: number; toolLevel: number; stepPct: number }>;
  capsule: Readonly<{ spinCost: number; timedSeconds: number; movementMultiplier: number; miningSpeedMultiplier: number;
    luckMultiplier: number; sellMultiplier: number; prizes: readonly Readonly<{ id: string; weight: number }>[] }>;
  luckyCoins: Readonly<{ signin: readonly number[]; online: readonly Readonly<{ minutes: number; coins: number }>[]; share: number; invite: number }>;
}>;

/** Two significant figures at most (480, 4 500, 12 000), the only kind of number a player sees. */
export function isRound(value: number) {
  if (!Number.isSafeInteger(value) || value < 0) return false;
  if (value < 100) return true;
  const unit = 10 ** (Math.floor(Math.log10(value)) - 1);
  return value % unit === 0;
}
function check(condition: unknown, message: string): asserts condition { if (!condition) throw Error(`economy.json: ${message}`); }
const round = (value: number, what: string) => check(isRound(value), `${what} 不是整齐的数 (${value})`);
const rising = (values: readonly number[], what: string) => values.forEach((v, i) => check(i === 0 || v > values[i - 1], `${what} 没有逐级上升`));

export function validateEconomy(e: Economy): Economy {
  const ids = e.currencies.map(c => c.id);
  check(ids.join() === 'gold,tech,star' && e.currencies.every((c, i) => c.world === i + 1), '货币必须是金币、科技币、星晶，各属一个世界');
  const currencyOf = (world: number) => ids[world - 1];
  check(e.worlds.length === 3 && e.worlds.every((w, i) => w.id === i + 1 && w.currency === currencyOf(w.id)), '世界与货币不对应');
  for (const w of e.worlds) {
    check((w.id === 1) === !w.ticket, '只有第二、三世界有门票');
    if (!w.ticket) continue;
    check(w.ticket.currency === currencyOf(w.id - 1), `第${w.id}世界门票要用上一世界的货币`);
    round(w.ticket.price, '门票价格');
    check(w.ticket.toolLevel === e.layers[(w.id - 1) * 7].gate, `第${w.id}世界门票的镐子等级要等于它地表的门槛`);
    for (const m of w.ticket.materials) {
      check(m.world < w.id && e.layers[(m.world - 1) * 7 + m.layer]?.ores.some(o => o.itemId === m.itemId), `门票材料 ${m.itemId} 不在它写的层里`);
      check(Number.isSafeInteger(m.count) && m.count > 0, '门票材料数量无效');
    }
  }
  check(e.layers.length === 21, '每个世界 7 层，共 21 层');
  e.layers.forEach((l, i) => {
    const local = i % 7, next = local < 6 ? e.layers[i + 1] : null;
    check(l.world === Math.floor(i / 7) + 1 && l.layer === local, `第 ${i} 层的世界或层号错`);
    check(local === 0 ? l.from === 0 : l.from > e.layers[i - 1].from && l.from % 2 === 0, `第 ${i} 层深度错`);
    check(next ? l.deepAt !== null && l.deepAt % 2 === 0 && l.deepAt > 0 && l.deepAt < next.from - l.from : l.deepAt === null, `第 ${i} 层致密岩深度错`);
    check(i === 0 || l.gate >= e.layers[i - 1].gate, `第 ${i} 层门槛倒退`);
    check(l.oreChance > 0 && l.oreChance < 1, `第 ${i} 层矿石概率错`);
    round(l.capsuleCoins, '扭蛋金币');
    for (const b of [l.rock, l.deep, ...l.ores]) { round(b.hp, `${b.itemId} 血量`); round(b.price, `${b.itemId} 售价`); check(b.hp > 0 && b.price > 0, `${b.itemId} 血量或售价为 0`); }
    check(l.ores.length === 2 && l.ores.every(o => o.weight > 0), `第 ${i} 层矿石配置错`);
  });
  check(e.tools.length === 30 && e.tools.every((t, i) => t.level === i + 1 && t.currency === currencyOf(Math.floor(i / 10) + 1)), '镐子 30 级，每世界 10 级');
  rising(e.tools.map(t => t.power), '镐子伤害');
  e.tools.forEach((t, i) => {
    round(t.price, '镐子价格'); round(t.power, '镐子伤害');
    check(t.speed > 0 && t.speed <= 4 * e.tools[0].speed && (i === 0 || t.speed >= e.tools[i - 1].speed), '攻速要逐级不降，最多是初始的 4 倍');
    check(i === 0 ? t.price === 0 : i % 10 === 0 || t.price > e.tools[i - 1].price, `镐子 L${t.level} 价格没有上升`);
    check(t.enhance.length === (t.level < 30 ? 3 : 0), `镐子 L${t.level} 强化次数错`);
    rising([t.power, ...t.enhance.map(x => x.power)], `镐子 L${t.level} 强化伤害`);
    rising(t.enhance.map(x => x.price), `镐子 L${t.level} 强化价格`);
    t.enhance.forEach(x => { round(x.price, '强化价格'); round(x.power, '强化伤害'); });
  });
  check(e.bags.length === 30 && e.bags.every((b, i) => b.tier === i + 1 && b.currency === currencyOf(Math.floor(i / 10) + 1)), '背包 30 档，每世界 10 档');
  rising(e.bags.map(b => b.capacity), '背包容量');
  e.bags.forEach((b, i) => { round(b.price, '背包价格'); check(i === 0 ? b.price === 0 : i % 10 === 0 || b.price > e.bags[i - 1].price, `背包第 ${b.tier} 档价格没有上升`); });
  check(e.start.toolLevel === 1 && e.start.bagTier === 1 && e.start.petSlots > 0, '开局配置错');
  e.petSlots.forEach((s, i) => { check(s.slot === e.start.petSlots + i + 1 && s.currency === currencyOf(s.world), '宠物栏位配置错'); round(s.price, '栏位价格'); });
  const eggIds = new Set<string>(), petIds = new Set<string>();
  for (const egg of e.eggs) {
    check(egg.currency === currencyOf(egg.world) && egg.layer >= 0 && egg.layer < 7, `蛋 ${egg.id} 的世界或货币错`);
    round(egg.price, '蛋价'); check(egg.price > 0, '蛋价为 0');
    check(egg.pets.length > 0 && egg.pets.every(p => p.weight > 0 && p.bonusPct > 0 && isRound(p.bonusPct) && p.miningPct > 0 && isRound(p.miningPct)), `蛋 ${egg.id} 的宠物配置错`);
    if (egg.id === null) { check(egg.pets.every(p => p.id === null), '没有名字的蛋不能有宠物名'); continue; }
    check(!eggIds.has(egg.id), `重复的蛋 ${egg.id}`); eggIds.add(egg.id);
    for (const p of egg.pets) { check(p.id && !petIds.has(p.id), `重复或缺少的宠物 ${p.id}`); petIds.add(p.id!); }
  }
  check(e.golden.need > 1 && e.golden.bonusMultiplier > 1, '金色宠物配置错');
  check(e.rebirth.toolLevel === 30 && e.rebirth.stepPct > 0, '重生配置错');
  check(e.capsule.prizes.every(p => p.weight > 0), '扭蛋奖品权重错');
  return e;
}

export const ECONOMY: Economy = validateEconomy(data as Economy);
export const CURRENCY_IDS: readonly CurrencyId[] = ECONOMY.currencies.map(c => c.id);
export const currencyOfWorld = (world: number): CurrencyId => ECONOMY.worlds[world - 1].currency;
export const currencyName = (id: CurrencyId) => ECONOMY.currencies.find(c => c.id === id)!.name;
/** A layer's numbers by world and local layer (0 = the surface). */
export const layerEconomy = (world: number, layer: number) => ECONOMY.layers[(world - 1) * 7 + layer];
